select pg_temp.assert((select relrowsecurity from pg_class where oid='private.occasions'::regclass),'occasions RLS');
select pg_temp.assert((select relrowsecurity from pg_class where oid='private.occasion_verifications'::regclass),'verifications RLS');
select pg_temp.assert(not has_table_privilege('anon','private.occasions','SELECT'),'anon cannot read table');
select pg_temp.assert(not has_table_privilege('authenticated','private.occasion_verifications','INSERT'),'authenticated cannot submit directly');
select pg_temp.assert(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and proname like 'occasion_%_internal' and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE') or not has_function_privilege('service_role',p.oid,'EXECUTE') or p.proconfig is distinct from array['search_path=""'])),'RPC privileges and empty search_path');
select pg_temp.assert((select count(*)=6 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and proname like 'occasion_%_internal'),'six internal RPCs');

create temporary table state(key text primary key,value jsonb);
insert into state values ('input','{"date_start":"2026-12-25","date_end":null,"estimated_date":null,"name_zh":"Holiday","name_en":"Holiday","category":"festival","location_or_audience":"Kuching","flower_demand":"high","typical_products":["bouquet"],"order_lead_days":21,"recurrence":"fixed","date_status":"pattern","confidence":"medium","past_2024":null,"past_2025":null,"source_url":"https://example.com/date","evidence":null}');
select pg_temp.expect_error($q$select public.occasion_list_internal('44444444-4444-4444-8444-444444444444','agent')$q$,'occasion_agent_required');
select pg_temp.expect_error($q$select public.occasion_list_internal('55555555-5555-4555-8555-555555555555','owner')$q$,'forbidden');
select pg_temp.expect_error($q$select public.occasion_upsert_internal('22222222-2222-4222-8222-222222222222',(select value from state where key='input'),null,false)$q$,'forbidden');
insert into state select 'occasion',public.occasion_upsert_internal('11111111-1111-4111-8111-111111111111',value,null,false)->'occasion' from state where key='input';
select pg_temp.assert((select value->>'verified_by' is null from state where key='occasion'),'unconfirmed has no provenance');
select pg_temp.assert(not (public.occasion_stock_eligibility_internal('22222222-2222-4222-8222-222222222222',(select (value->>'id')::uuid from state where key='occasion'))->>'allowed')::boolean,'pattern blocked');
insert into state select 'verification',public.occasion_verification_submit_internal('22222222-2222-4222-8222-222222222222',jsonb_build_object('occasion_id',value->>'id','proposed_date_start','2027-01-01','proposed_date_end',null,'proof_url','https://school.example/date','note','School source'))->'verification' from state where key='occasion';
select pg_temp.assert((select date_status='pattern' and date_start='2026-12-25' from private.occasions where id=(select (value->>'id')::uuid from state where key='occasion')),'agent submission cannot alter occasion');
select pg_temp.assert(jsonb_array_length(public.occasion_list_internal('33333333-3333-4333-8333-333333333333','agent')->'verifications')=0,'agent B sees no agent A verification');
select pg_temp.assert(jsonb_array_length(public.occasion_list_internal('22222222-2222-4222-8222-222222222222','agent')->'verifications')=1,'agent A sees own verification');
select pg_temp.assert(jsonb_array_length(public.occasion_list_internal('11111111-1111-4111-8111-111111111111','owner')->'verifications')=1,'owner sees pending');
insert into state select 'approved',public.occasion_verification_review_internal('11111111-1111-4111-8111-111111111111',(value->>'id')::uuid,'approved') from state where key='verification';
select pg_temp.assert((select value->'occasion'->>'verified_by'='11111111-1111-4111-8111-111111111111' and value->'occasion'->>'date_status'='confirmed' and value->'occasion'->>'source_url'='https://school.example/date' and value->'occasion'->>'evidence'='School source' from state where key='approved'),'approval attributes to owner and copies source');
select pg_temp.assert((public.occasion_stock_eligibility_internal('22222222-2222-4222-8222-222222222222',(select (value->>'id')::uuid from state where key='occasion'))->>'allowed')::boolean,'owner verified date eligible');
select pg_temp.expect_error($q$select public.occasion_verification_review_internal('11111111-1111-4111-8111-111111111111',(select (value->>'id')::uuid from state where key='verification'),'rejected')$q$,'occasion_verification_already_reviewed');
-- Provenance alone is insufficient when the owner role has been removed.
delete from private.user_roles where user_id='11111111-1111-4111-8111-111111111111';
select pg_temp.assert(not (public.occasion_stock_eligibility_internal('22222222-2222-4222-8222-222222222222',(select (value->>'id')::uuid from state where key='occasion'))->>'allowed')::boolean,'former-owner provenance blocked');
insert into private.user_roles values ('11111111-1111-4111-8111-111111111111','owner');
-- Two pending proposals cannot overwrite each other after the first approval.
insert into state select 'proposal2',public.occasion_verification_submit_internal('22222222-2222-4222-8222-222222222222',jsonb_build_object('occasion_id',value->>'id','proposed_date_start','2027-01-02','proposed_date_end',null,'proof_url',null,'note','Second proposal'))->'verification' from state where key='occasion';
insert into state select 'proposal3',public.occasion_verification_submit_internal('33333333-3333-4333-8333-333333333333',jsonb_build_object('occasion_id',value->>'id','proposed_date_start','2027-01-03','proposed_date_end',null,'proof_url',null,'note','Conflicting proposal'))->'verification' from state where key='occasion';
select public.occasion_verification_review_internal('11111111-1111-4111-8111-111111111111',(select (value->>'id')::uuid from state where key='proposal2'),'approved');
select pg_temp.expect_error($q$select public.occasion_verification_review_internal('11111111-1111-4111-8111-111111111111',(select (value->>'id')::uuid from state where key='proposal3'),'approved')$q$,'occasion_verification_stale');
select pg_temp.assert((select status='pending' from private.occasion_verifications where id=(select (value->>'id')::uuid from state where key='proposal3')),'failed conflicting approval is atomic');
select public.occasion_verification_review_internal('11111111-1111-4111-8111-111111111111',(select (value->>'id')::uuid from state where key='proposal3'),'rejected');
select pg_temp.assert((select date_start='2027-01-02' from private.occasions where id=(select (value->>'id')::uuid from state where key='occasion')),'rejection preserves occasion');
-- Import true discards confirmation/provenance, false explicitly attests to owner.
select public.occasion_import_internal('11111111-1111-4111-8111-111111111111',jsonb_build_array((select value from state where key='input')||'{"id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","date_status":"confirmed","needs_owner_confirm":true,"verified_by":"22222222-2222-4222-8222-222222222222","verified_at":"2026-01-01T00:00:00Z"}'::jsonb));
select pg_temp.assert((select date_status='pattern' and date_start is null and estimated_date='2026-12-25' and verified_by is null and verified_at is null from private.occasions where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'needs confirmation import cannot lock stock');
select public.occasion_import_internal('11111111-1111-4111-8111-111111111111',jsonb_build_array((select value from state where key='input')||'{"id":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb","date_status":"confirmed","needs_owner_confirm":false,"verified_by":"22222222-2222-4222-8222-222222222222","verified_at":"2026-01-01T00:00:00Z"}'::jsonb));
select pg_temp.assert((select verified_by='11111111-1111-4111-8111-111111111111' and verified_at>'2026-11-01' from private.occasions where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'CSV provenance replaced by server owner');
select pg_temp.expect_error($q$select public.occasion_import_internal('11111111-1111-4111-8111-111111111111','[]')$q$,'occasion_invalid_request');
select pg_temp.expect_error($q$select public.occasion_upsert_internal('11111111-1111-4111-8111-111111111111',(select value from state where key='input')||'{"date_start":"2026-02-29"}',null,false)$q$,'occasion_invalid_request');
select pg_temp.expect_error($q$select public.occasion_upsert_internal('11111111-1111-4111-8111-111111111111',(select value from state where key='input')||'{"source_url":"javascript:alert(1)"}',null,false)$q$,'occasion_invalid_request');
select pg_temp.expect_error($q$select public.occasion_upsert_internal('11111111-1111-4111-8111-111111111111',(select value from state where key='input')||'{"date_status":"confirmed"}',null,false)$q$,'occasion_confirmation_required');
select pg_temp.expect_error($q$select public.occasion_import_internal('11111111-1111-4111-8111-111111111111',jsonb_build_array((select value from state where key='input')||'{"id":"cccccccc-cccc-4ccc-8ccc-cccccccccccc","needs_owner_confirm":false}',(select value from state where key='input')||'{"needs_owner_confirm":false,"order_lead_days":1000}'))$q$,'occasion_invalid_request');
select pg_temp.assert(not exists(select 1 from private.occasions where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc'),'import batch rollback');
select pg_temp.expect_error($q$select public.occasion_import_internal('11111111-1111-4111-8111-111111111111',jsonb_build_array((select value from state where key='input')||'{"needs_owner_confirm":false,"verified_at":"2026-01-01T24:00:00Z"}'))$q$,'occasion_invalid_request');
select pg_temp.expect_error($q$select public.occasion_import_internal('11111111-1111-4111-8111-111111111111',(select jsonb_agg(value||'{"needs_owner_confirm":false}'::jsonb) from state cross join generate_series(1,201) where key='input'))$q$,'occasion_invalid_request');
select pg_temp.expect_error($q$select public.occasion_verification_review_internal('55555555-5555-4555-8555-555555555555',(select (value->>'id')::uuid from state where key='verification'),'rejected')$q$,'forbidden');
select pg_temp.expect_error($q$select public.occasion_verification_submit_internal('44444444-4444-4444-8444-444444444444','{}')$q$,'occasion_agent_required');
select pg_temp.expect_error($q$select public.occasion_upsert_internal('11111111-1111-4111-8111-111111111111',(select value from state where key='input')||'{"verified_by":"11111111-1111-4111-8111-111111111111"}',null,false)$q$,'occasion_invalid_request');
select pg_temp.expect_error($q$update private.occasions set date_status='confirmed' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$q$,'occasions_confirmation_metadata');
